const fs = require('fs');
const path = require('path');
const dir = 'c:/Dev/PATTOOL2/PatTool_Front-End/src/assets/i18n';
const byLang = {
  fr: {
    AUTO_FOUND: 'Objet identifié',
    AUTO_SEP: 'à {{deg}}° de votre visée',
    AUTO_OTHERS: 'Autres candidats proches'
  },
  en: {
    AUTO_FOUND: 'Object identified',
    AUTO_SEP: '{{deg}}° from your aim',
    AUTO_OTHERS: 'Other nearby candidates'
  },
  de: {
    AUTO_FOUND: 'Objekt erkannt',
    AUTO_SEP: '{{deg}}° von Ihrer Zielrichtung',
    AUTO_OTHERS: 'Weitere nahe Kandidaten'
  },
  es: {
    AUTO_FOUND: 'Objeto identificado',
    AUTO_SEP: 'a {{deg}}° de tu apuntado',
    AUTO_OTHERS: 'Otros candidatos cercanos'
  },
  it: {
