    AUTO_SEP: 'a {{deg}}° dalla mira',
    AUTO_OTHERS: 'Altri candidati vicini'
  },
  ru: {
    AUTO_FOUND: 'Объект опознан',
    AUTO_SEP: 'в {{deg}}° от наведения',
    AUTO_OTHERS: 'Другие близкие кандидаты'
  },
  cn: {
    AUTO_FOUND: '已识别天体',
    AUTO_SEP: '距瞄准方向 {{deg}}°',
    AUTO_OTHERS: '附近其他候选'
  },
  jp: {
    AUTO_FOUND: '天体を識別しました',
    AUTO_SEP: '照準から {{deg}}°',
    AUTO_OTHERS: '近くの他の候補'
  },
  ar: {
    AUTO_FOUND: 'تم التعرف على الجرم',
    AUTO_SEP: 'على بعد {{deg}}° من التوجيه',
    AUTO_OTHERS: 'مرشحون قريبون آخرون'
  },
  he: {
    AUTO_FOUND: 'עצם זוהה',
    AUTO_SEP: '{{deg}}° מכיוון הכיוון',
    AUTO_OTHERS: 'מועמדים קרובים נוספים'
  },
  el: {
